query Inventory(
  $whereInventory: InventoryWhereInput, 
  $whereHandlingUnit: HandlingUnitWhereInput
) {
  inventory(where: $whereInventory) {
    ...InventoryInfo
  }

  handlingUnit(where: $whereHandlingUnit) {
    edges {
      node {
        id
        active
        parentHandlingUnitId
        mixed
        inventories {
          ...InventoryInfo
        }
      }
    }
  }
}

fragment InventoryInfo on InventoryConnection {
  edges {
    node {
      id
      serialNumber
      productId

        active
        inventoryStatusId
        handlingUnitId
        storageUnit {
          id
          active
          storageUnitStatusId
        }

    }
  }
}

query ($productId: String!){
  productPreferredStorageUnit(
    where:  {
       productId:  {
          _eq: $productId
       }
       storageUnit:  {
          _or: [ 
            {
              inventories:  {
                  _all:  {
                    productId:  {
                        _eq: $productId
                    }
                  }
              }
            },
            {
              inventories:  {
                 _all:  {
                    productId:  {
                       _isNull: true
                    }
                 }
              }
            }
          ]
       }
    }
    first: 10
    orderBy: [ {
       direction: asc
       field: priority
    }]
  ){
    edges{
      node{
        storageUnit{
          id code
        }
      }
    }
  }
}

