query (
  $serialNumber: String!,
  $storageUnit: String!
){
  inventory(where:  {
     serialNumber:  {
        _eq: $serialNumber
     }
  }){
    edges{
      node{
        quantity{ value}
        product{
          productPreferredStorageUnits(
            where:  {
               storageUnit:  {
                  code:{
                    _eq: $storageUnit
                  }
               }
            }
          ){
            total
          }
        }
      }
    }
  }

  handlingUnit(where:  {
     serialNumber:  {
        _eq: $serialNumber
     }
  }){
    edges{
      node{
        inventories{
          edges{
            node{
              product{
                productPreferredStorageUnits(where:  {
                   storageUnit:  {
                      code:  {
                         _eq: $storageUnit
                      }
                   }
                }){
                  total
                }
              }
              quantity{
                _aggregate{
                  value{
                    sum
                  }
                }
              }
              }
            }
          }
        }
      }
  }

  storageUnit(where:  {
     code:{
      _eq: $storageUnit
     }
  }){
    total
  }
}

